$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'windows-ocr.ps1')

function Fail([string]$Message) { [Console]::Error.WriteLine($Message); exit 1 }
function Output($Value) { $Value | ConvertTo-Json -Depth 12 -Compress; exit 0 }
function Get-RequiredParam($Name) { $value = $request.params.$Name; if ($null -eq $value) { Fail "Missing document parameter: $Name" }; return $value }
function Get-OptionalParam($Name) { return $request.params.$Name }
function Run-External([string]$Name, [string[]]$Arguments) {
  $command = Get-Command $Name -ErrorAction SilentlyContinue
  if ($null -eq $command) { Fail "The document backend requires '$Name', which is not installed or not on PATH." }
  $output = & $command.Source @Arguments 2>&1
  if ($LASTEXITCODE -ne 0) { Fail (($output | Out-String).Trim()) }
  return ($output | Out-String).Trim()
}
function Pdf-PageCount([string]$DocumentPath) { $info = Run-External 'pdfinfo' @($DocumentPath); $match = [regex]::Match($info, '(?m)^Pages:\s*(\d+)'); if (-not $match.Success) { throw 'Unable to determine the PDF page count.' }; return [int]$match.Groups[1].Value }
function Pdf-SelectedPages([string]$DocumentPath) { $pages = $request.params.pages; if ($null -eq $pages -or @($pages).Count -eq 0) { return 0..([Math]::Min((Pdf-PageCount $DocumentPath) - 1, 99)) }; $selected = @($pages | ForEach-Object { [int]$_ } | Where-Object { $_ -ge 0 }); if ($selected.Count -gt 100) { throw 'The PDF page selection exceeds the 100-page limit.' }; return $selected }
function Pdf-ExplicitPages() { $pages = $request.params.pages; if ($null -eq $pages -or @($pages).Count -eq 0) { return $null }; $selected = @($pages | ForEach-Object { if ($_ -isnot [int] -and $_ -isnot [long]) { throw 'PDF pages must be integers.' }; [int]$_ }); if ($selected | Where-Object { $_ -lt 0 }) { throw 'PDF pages must be non-negative.' }; if ($selected.Count -gt 100 -or (@($selected | Sort-Object -Unique).Count -ne $selected.Count)) { throw 'PDF pages must be unique and contain no more than 100 entries.' }; return @($selected | Sort-Object) }
function Read-PdfText([string]$DocumentPath) { $selected = Pdf-ExplicitPages; if ($null -eq $selected) { return Run-External 'pdftotext' @('-layout', $DocumentPath, '-') }; $chunks = @(); foreach ($page in $selected) { $chunks += Run-External 'pdftotext' @('-layout', '-f', ([string]($page + 1)), '-l', ([string]($page + 1)), $DocumentPath, '-') }; return ($chunks -join "`f") }
function Extract-PdfImages([string]$DocumentPath) { $outputDirectory = [string](Get-RequiredParam 'outputPath'); New-Item -ItemType Directory -Path $outputDirectory -Force | Out-Null; $selected = Pdf-ExplicitPages; $prefixes = if ($null -eq $selected) { @((Join-Path $outputDirectory 'image')) } else { @($selected | ForEach-Object { Join-Path $outputDirectory ('image-page-' + ([int]$_ + 1).ToString('D4')) }) }; if ($null -eq $selected) { Run-External 'pdfimages' @('-png', $DocumentPath, $prefixes[0]) | Out-Null } else { for ($index = 0; $index -lt $selected.Count; $index++) { Run-External 'pdfimages' @('-png', '-f', ([string]($selected[$index] + 1)), '-l', ([string]($selected[$index] + 1)), $DocumentPath, $prefixes[$index]) | Out-Null } }; $files = if ($null -eq $selected) { @(Get-ChildItem -LiteralPath $outputDirectory -Filter 'image-*' -File | Sort-Object Name | ForEach-Object FullName) } else { @($prefixes | ForEach-Object { $prefix = [IO.Path]::GetFileName($_); Get-ChildItem -LiteralPath $outputDirectory -Filter ($prefix + '-*') -File | Sort-Object Name | ForEach-Object FullName }) }; return @{ format = 'pdf'; outputPath = $outputDirectory; files = $files } }
function Render-Pdf([string]$DocumentPath) { $requested = if ($null -eq $request.params.outputPath) { "$DocumentPath.png" } else { [string]$request.params.outputPath }; if ([string]::IsNullOrWhiteSpace($requested)) { $requested = "$DocumentPath.png" }; $directory = [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($requested)); New-Item -ItemType Directory -Path $directory -Force | Out-Null; $prefix = [IO.Path]::ChangeExtension($requested, $null); $selected = Pdf-ExplicitPages; $files = @(); if ($null -eq $selected) { Run-External 'pdftoppm' @('-png', $DocumentPath, $prefix) | Out-Null; $files = @(Get-ChildItem -LiteralPath $directory -File | Where-Object { $_.Name.StartsWith([IO.Path]::GetFileName($prefix), [StringComparison]::Ordinal) -and $_.Extension -eq '.png' } | Sort-Object Name | ForEach-Object FullName) } else { for ($index = 0; $index -lt $selected.Count; $index++) { $pagePrefix = if ($selected.Count -eq 1 -and [IO.Path]::GetExtension($requested).ToLowerInvariant() -eq '.png') { $prefix } else { Join-Path $directory ([IO.Path]::GetFileName($prefix) + '-page-' + ([int]$selected[$index] + 1).ToString('D4')) }; Run-External 'pdftoppm' @('-png', '-singlefile', '-f', ([string]($selected[$index] + 1)), '-l', ([string]($selected[$index] + 1)), $DocumentPath, $pagePrefix) | Out-Null; $files += "$pagePrefix.png" } }; return @{ format = 'pdf'; path = $requested; files = $files } }
function Read-PdfBookmarks([string]$DocumentPath) { $dump = Run-External 'pdftk' @($DocumentPath, 'dump_data_utf8'); $items = @(); $current = $null; foreach ($line in ($dump -split "`r?`n")) { if ($line -like 'BookmarkTitle: *') { if ($null -ne $current) { $items += $current }; $current = [ordered]@{ title = $line.Substring(15); level = 1; page = 0 } } elseif ($null -ne $current -and $line -like 'BookmarkLevel: *') { $current.level = [int]$line.Substring(15) } elseif ($null -ne $current -and $line -like 'BookmarkPageNumber: *') { $current.page = [int]$line.Substring(20) - 1 } }; if ($null -ne $current) { $items += $current }; return $items }
function Update-PdfBookmarks([string]$DocumentPath, [string]$Operation) { $bookmark = Get-OptionalParam 'bookmark'; $items = @(Read-PdfBookmarks $DocumentPath); if ($Operation -eq 'add') { if ($null -eq $bookmark.title -or $null -eq $bookmark.page) { throw 'A bookmark title and page are required.' }; $items += [ordered]@{ title = [string]$bookmark.title; level = if ($null -eq $bookmark.level) { 1 } else { [int]$bookmark.level }; page = [int]$bookmark.page } } elseif ($Operation -eq 'update' -or $Operation -eq 'delete') { $index = [int]$bookmark.index; if ($index -lt 0 -or $index -ge $items.Count) { throw 'The bookmark index is invalid.' }; if ($Operation -eq 'delete') { $items = @($items | Where-Object { $_ -ne $items[$index] }) } else { if ($null -ne $bookmark.title) { $items[$index].title = [string]$bookmark.title }; if ($null -ne $bookmark.page) { $items[$index].page = [int]$bookmark.page }; if ($null -ne $bookmark.level) { $items[$index].level = [int]$bookmark.level } } } else { throw "Unsupported PDF bookmark operation '$Operation'." }; $lines = @('InfoBegin', 'InfoKey: ModDate', ('InfoValue: D:' + (Get-Date -Format 'yyyyMMddHHmmss')), 'InfoBegin'); foreach ($item in $items) { $lines += 'BookmarkBegin'; $lines += "BookmarkTitle: $($item.title)"; $lines += "BookmarkLevel: $($item.level)"; $lines += "BookmarkPageNumber: $([int]$item.page + 1)" }; $infoPath = "$DocumentPath.$([guid]::NewGuid()).bookmarks.txt"; $temporary = "$DocumentPath.$([guid]::NewGuid()).pdf"; try { [IO.File]::WriteAllLines($infoPath, $lines, [Text.Encoding]::UTF8); Run-External 'pdftk' @($DocumentPath, 'update_info_utf8', $infoPath, 'output', $temporary) | Out-Null; Move-Item -LiteralPath $temporary -Destination $DocumentPath -Force } finally { Remove-Item -LiteralPath $infoPath -Force -ErrorAction SilentlyContinue; Remove-Item -LiteralPath $temporary -Force -ErrorAction SilentlyContinue }; return $items }
function Assert-Extension([string]$DocumentPath, [string]$Format) {
  $extension = [IO.Path]::GetExtension($DocumentPath).ToLowerInvariant()
  $allowed = @{ pdf = @('.pdf'); pptx = @('.pptx'); excel = @('.xlsx', '.xls', '.csv'); docs = @('.docx', '.doc', '.txt', '.rtf') }[$Format]
  if ($allowed -notcontains $extension) { Fail "The path extension does not match the $Format document plugin." }
}
function Release-Com([object]$Value) { if ($null -ne $Value -and [Runtime.InteropServices.Marshal]::IsComObject($Value)) { [Runtime.InteropServices.Marshal]::FinalReleaseComObject($Value) | Out-Null } }
function New-Pdf([string]$Target, [string]$Title) {
  $safeTitle = $Title -replace '[()]', ''
  $objects = @('<< /Type /Catalog /Pages 2 0 R >>', '<< /Type /Pages /Kids [3 0 R] /Count 1 >>', '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>', "<< /Length $($safeTitle.Length + 38) >>`nstream`nBT /F1 18 Tf 72 720 Td ($safeTitle) Tj ET`nendstream", '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>')
  $text = New-Object Text.StringBuilder; [void]$text.AppendLine('%PDF-1.4'); $offsets = @();
  for ($index = 0; $index -lt $objects.Count; $index++) { $objectNumber = $index + 1; $offsets += $text.Length; [void]$text.AppendLine("$objectNumber 0 obj"); [void]$text.AppendLine($objects[$index]); [void]$text.AppendLine('endobj') }
  $xref = $text.Length; [void]$text.AppendLine('xref'); [void]$text.AppendLine("0 $($objects.Count)"); [void]$text.AppendLine('0000000000 65535 f '); foreach ($offset in $offsets) { [void]$text.AppendLine(('{0:D10} 00000 n ' -f $offset)) }; [void]$text.AppendLine('trailer'); [void]$text.AppendLine("<< /Size $($objects.Count) /Root 1 0 R >>"); [void]$text.AppendLine('startxref'); [void]$text.AppendLine([string]$xref); [void]$text.AppendLine('%%EOF'); [IO.File]::WriteAllText($Target, $text.ToString(), [Text.Encoding]::ASCII)
}
function Office-App([string]$Format) { if ($Format -eq 'docs') { return New-Object -ComObject Word.Application }; if ($Format -eq 'excel') { return New-Object -ComObject Excel.Application }; return New-Object -ComObject PowerPoint.Application }
function Office-Open([string]$Format, [string]$DocumentPath, [object]$App) {
  if ($Format -eq 'docs') { return $App.Documents.Open($DocumentPath, $false, $false) }
  if ($Format -eq 'excel') { return $App.Workbooks.Open($DocumentPath) }
  return $App.Presentations.Open($DocumentPath, $true, $false, $false)
}
function Office-Close([string]$Format, [object]$Document, [object]$App) {
  if ($null -ne $Document) { if ($Format -eq 'docs') { $Document.Close($false) } elseif ($Format -eq 'excel') { $Document.Close($false) } else { $Document.Close() } }
  if ($null -ne $App) { $App.Quit() }; Release-Com $Document; Release-Com $App
}
function Office-Sheet([object]$Document) { if ($null -eq (Get-OptionalParam 'sheet')) { return $Document.Worksheets.Item(1) }; return $Document.Worksheets.Item([string](Get-OptionalParam 'sheet')) }
function Office-Slide([object]$Document) { return $Document.Slides.Item(([int](Get-RequiredParam 'slide')) + 1) }
function Office-Range([object]$Document) { return $Document.Range([int](Get-RequiredParam 'start'), [int](Get-RequiredParam 'end')) }
function Escape-CsvValue([object]$Value) { $text = if ($null -eq $Value -or $Value -is [DBNull]) { '' } else { [string]$Value }; if ($text.Contains(',') -or $text.Contains('"') -or $text.Contains("`r") -or $text.Contains("`n")) { return '"' + $text.Replace('"', '""') + '"' }; return $text }
function Export-ExcelCsv([object]$Sheet, [string]$OutputPath) { $range = if ($null -eq $request.params.range) { $Sheet.UsedRange } else { $Sheet.Range([string](Get-RequiredParam 'range')) }; New-Item -ItemType Directory -Path ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($OutputPath))) -Force | Out-Null; $values = $range.Value2; $lines = New-Object 'System.Collections.Generic.List[string]'; if ($values -is [Array] -and $values.Rank -ge 2) { for ($row = 0; $row -lt $values.GetLength(0); $row++) { $cells = @(); for ($column = 0; $column -lt $values.GetLength(1); $column++) { $cells += Escape-CsvValue $values[$row + 1, $column + 1] }; $lines.Add(($cells -join ',')) } } else { $lines.Add((Escape-CsvValue $values)) }; [IO.File]::WriteAllLines($OutputPath, $lines, [Text.UTF8Encoding]::new($false)); return @{ path = $OutputPath; exported = $true; sheet = [string]$Sheet.Name; range = if ($null -eq $request.params.range) { [string]$range.Address() } else { [string]$request.params.range } } }
function Pptx-SelectedSlides([object]$Document) { $pages = $request.params.pages; if ($null -eq $pages -or @($pages).Count -eq 0) { return @(1..$Document.Slides.Count) }; $selected = @($pages | ForEach-Object { $value = [int]$_; if ($value -lt 0 -or $value -ge $Document.Slides.Count) { throw 'Presentation pages contain an invalid slide index.' }; $value + 1 }); if ((@($selected | Sort-Object -Unique).Count -ne $selected.Count)) { throw 'Presentation pages must be unique.' }; return $selected }
function Replace-PptxText([object]$Document) { $findText = [string](Get-RequiredParam 'find'); $replaceText = [string](Get-RequiredParam 'replace'); $count = 0; $selected = Pptx-SelectedSlides $Document; foreach ($slideIndex in $selected) { foreach ($shape in $Document.Slides.Item($slideIndex).Shapes) { if ($shape.HasTextFrame -and $shape.TextFrame.HasText) { $range = $shape.TextFrame.TextRange; $before = [string]$range.Text; $after = $before.Replace($findText, $replaceText); if ($before -ne $after) { $range.Text = $after; $count++ } } } }; $Document.Save(); return @{ saved = $true; operation = 'findReplace'; replacements = $count; pages = @($selected | ForEach-Object { $_ - 1 }) } }
function Read-DocsExtended([object]$document, [string]$operation) {
  if ($operation -eq 'inspectStructure') { $paragraphs = @(); foreach ($paragraph in $document.Paragraphs) { if ($paragraphs.Count -ge 1000) { break }; $paragraphs += [ordered]@{ index = $paragraphs.Count; text = Bound-Text ([string]$paragraph.Range.Text.Trim()); style = [string]$paragraph.Style; outlineLevel = [int]$paragraph.OutlineLevel } }; $tables = @(); for ($i = 1; $i -le $document.Tables.Count; $i++) { $table = $document.Tables.Item($i); $tables += [ordered]@{ index = $i - 1; rows = $table.Rows.Count; columns = $table.Columns.Count } }; $sections = @(); for ($i = 1; $i -le $document.Sections.Count; $i++) { $sections += [ordered]@{ index = $i - 1; start = $document.Sections.Item($i).Range.Start; end = $document.Sections.Item($i).Range.End } }; Output @{ operation = $operation; paragraphs = $paragraphs; tables = $tables; sections = $sections } }
  if ($operation -eq 'manageBookmarks' -and [string]$request.params.operation -eq 'list') { $items = @(); foreach ($bookmark in $document.Bookmarks) { $items += [ordered]@{ name = [string]$bookmark.Name; start = [int]$bookmark.Range.Start; end = [int]$bookmark.Range.End; text = Bound-Text ([string]$bookmark.Range.Text) } }; Output @{ operation = 'list'; bookmarks = $items } }
  if ($operation -eq 'manageHyperlinks' -and [string]$request.params.operation -eq 'list') { $items = @(); foreach ($link in $document.Hyperlinks) { $items += [ordered]@{ address = [string]$link.Address; subAddress = [string]$link.SubAddress; text = Bound-Text ([string]$link.Range.Text); start = [int]$link.Range.Start; end = [int]$link.Range.End } }; Output @{ operation = 'list'; hyperlinks = $items } }
  if ($operation -eq 'manageLists' -and [string]$request.params.operation -eq 'list') { $items = @(); foreach ($paragraph in $document.Paragraphs) { if ($items.Count -ge 1000) { break }; if ([int]$paragraph.Range.ListFormat.ListType -ne 0) { $items += [ordered]@{ text = Bound-Text ([string]$paragraph.Range.Text.Trim()); level = [int]$paragraph.Range.ListFormat.ListLevelNumber; type = [int]$paragraph.Range.ListFormat.ListType } } }; Output @{ operation = 'list'; items = $items } }
  if ($operation -eq 'manageFootnotes' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($i = 1; $i -le $document.Footnotes.Count; $i++) { $note = $document.Footnotes.Item($i); $items += [ordered]@{ index = $i - 1; text = Bound-Text ([string]$note.Range.Text); reference = [int]$note.Reference.Start } }; Output @{ operation = 'list'; footnotes = $items } }
  Fail "The docs read operation '$operation' is not supported by the installed Office backend."
}
function Read-ExcelExtended([object]$document, [string]$operation) {
  $sheet = Office-Sheet $document
  if ($operation -eq 'readFormulas') { $range = $sheet.Range([string](Get-RequiredParam 'range')); Output @{ operation = $operation; sheet = $sheet.Name; range = $range.Address(); formulas = $range.Formula; values = $range.Value2 } }
  if ($operation -eq 'manageConditionalFormatting' -and [string]$request.params.operation -eq 'list') { $range = $sheet.Range([string](Get-RequiredParam 'range')); $items = @(); for ($i = 1; $i -le $range.FormatConditions.Count; $i++) { $rule = $range.FormatConditions.Item($i); $items += [ordered]@{ index = $i - 1; type = [int]$rule.Type; operator = [int]$rule.Operator; formula1 = [string]$rule.Formula1; formula2 = [string]$rule.Formula2 } }; Output @{ operation = 'list'; sheet = $sheet.Name; range = $range.Address(); rules = $items } }
  if ($operation -eq 'manageSheetView' -and [string]$request.params.operation -eq 'list') { Output @{ operation = 'list'; sheet = $sheet.Name; visible = [int]$sheet.Visible; usedRange = $sheet.UsedRange.Address(); freezePanes = [bool]$document.Application.ActiveWindow.FreezePanes; zoom = [int]$document.Application.ActiveWindow.Zoom } }
  if ($operation -eq 'manageComments' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($i = 1; $i -le $sheet.Comments.Count; $i++) { $comment = $sheet.Comments.Item($i); $items += [ordered]@{ index = $i - 1; address = [string]$comment.Parent.Address(); text = Bound-Text ([string]$comment.Text()); author = [string]$comment.Author } }; Output @{ operation = 'list'; sheet = $sheet.Name; comments = $items } }
  if ($operation -eq 'manageProtection' -and [string]$request.params.operation -eq 'status') { $kind = if ($null -eq $request.params.kind) { 'worksheet' } else { [string]$request.params.kind }; $protected = if ($kind -eq 'workbook') { [bool]$document.ProtectStructure } else { [bool]$sheet.ProtectContents }; Output @{ operation = 'status'; kind = $kind; protected = $protected; sheet = $sheet.Name } }
  Fail "The excel read operation '$operation' is not supported by the installed Office backend."
}
function Read-PptxExtended([object]$document, [string]$operation) {
  if ($operation -eq 'extractText') { $slides = if ($null -eq $request.params.pages) { 1..$document.Slides.Count } else { @($request.params.pages | ForEach-Object { [int]$_ + 1 }) }; $items = @(); foreach ($number in $slides) { $slide = $document.Slides.Item($number); $text = New-Object Text.StringBuilder; foreach ($shape in $slide.Shapes) { if ($shape.HasTextFrame -and $shape.TextFrame.HasText) { [void]$text.AppendLine([string]$shape.TextFrame.TextRange.Text) } }; $items += [ordered]@{ slide = $number - 1; text = Bound-Text ($text.ToString().Trim()) } }; Output @{ operation = $operation; slides = $items } }
  if ($operation -eq 'manageMedia' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($s = 1; $s -le $document.Slides.Count; $s++) { foreach ($shape in $document.Slides.Item($s).Shapes) { if ([int]$shape.Type -in @(13, 16)) { $items += [ordered]@{ slide = $s - 1; elementId = [string]$shape.Name; type = [int]$shape.Type; left = $shape.Left; top = $shape.Top; width = $shape.Width; height = $shape.Height } } } }; Output @{ operation = 'list'; media = $items } }
  if ($operation -eq 'manageHyperlinks' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($s = 1; $s -le $document.Slides.Count; $s++) { foreach ($shape in $document.Slides.Item($s).Shapes) { $link = $shape.ActionSettings(1).Hyperlink; if ($null -ne $link -and (-not [string]::IsNullOrWhiteSpace([string]$link.Address) -or -not [string]::IsNullOrWhiteSpace([string]$link.SubAddress))) { $items += [ordered]@{ slide = $s - 1; elementId = [string]$shape.Name; address = [string]$link.Address; subAddress = [string]$link.SubAddress } } } }; Output @{ operation = 'list'; hyperlinks = $items } }
  if ($operation -eq 'manageTransitions' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($s = 1; $s -le $document.Slides.Count; $s++) { $transition = $document.Slides.Item($s).SlideShowTransition; $items += [ordered]@{ slide = $s - 1; entryEffect = [int]$transition.EntryEffect; advanceOnClick = [bool]$transition.AdvanceOnClick; advanceTime = [double]$transition.AdvanceTime } }; Output @{ operation = 'list'; transitions = $items } }
  if ($operation -eq 'manageLayouts' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($i = 1; $i -le $document.SlideMaster.CustomLayouts.Count; $i++) { $layout = $document.SlideMaster.CustomLayouts.Item($i); $items += [ordered]@{ index = $i - 1; name = [string]$layout.Name; type = [int]$layout.Type } }; Output @{ operation = 'list'; layouts = $items } }
  Fail "The pptx read operation '$operation' is not supported by the installed PowerPoint backend."
}
function Read-Office([string]$Format, [string]$DocumentPath, [string]$Operation) {
  $app = $null; $document = $null
  try {
    $app = Office-App $Format; $app.Visible = $false; $document = Office-Open $Format $DocumentPath $app
    if ($Format -eq 'docs' -and $Operation -in @('inspectStructure', 'manageBookmarks', 'manageHyperlinks', 'manageLists', 'manageFootnotes')) { Read-DocsExtended $document $Operation }
    if ($Format -eq 'excel' -and $Operation -in @('readFormulas', 'manageConditionalFormatting', 'manageSheetView', 'manageComments', 'manageProtection')) { Read-ExcelExtended $document $Operation }
    if ($Format -eq 'pptx' -and $Operation -in @('extractText', 'manageMedia', 'manageHyperlinks', 'manageTransitions', 'manageLayouts')) { Read-PptxExtended $document $Operation }
    if ($Format -eq 'docs' -and $Operation -eq 'readContent') { Output @{ content = [string]$document.Content.Text; format = 'docs' } }
    if ($Format -eq 'docs' -and $Operation -eq 'manageTable' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($index = 1; $index -le $document.Tables.Count; $index++) { $table = $document.Tables.Item($index); $items += [ordered]@{ index = $index - 1; rows = $table.Rows.Count; columns = $table.Columns.Count } }; Output @{ operation = 'list'; tables = $items } }
    if ($Format -eq 'docs' -and $Operation -eq 'manageTable' -and [string]$request.params.operation -eq 'read') { $table = $document.Tables.Item(([int](Get-RequiredParam 'index')) + 1); $rows = @(); for ($row = 1; $row -le $table.Rows.Count; $row++) { $cells = @(); for ($column = 1; $column -le $table.Columns.Count; $column++) { $cells += [string]$table.Cell($row, $column).Range.Text.Trim([char]13, [char]7) }; $rows += ,$cells }; Output @{ operation = 'read'; index = [int]$request.params.index; rows = $rows } }
    if ($Format -eq 'docs' -and $Operation -eq 'manageImage' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($index = 1; $index -le $document.InlineShapes.Count; $index++) { $image = $document.InlineShapes.Item($index); $items += [ordered]@{ index = $index - 1; width = $image.Width; height = $image.Height; altText = [string]$image.AlternativeText } }; Output @{ operation = 'list'; images = $items } }
    if ($Format -eq 'docs' -and $Operation -eq 'updateFields') { $updated = $document.Fields.Update(); Output @{ updated = [int]$updated } }
    if ($Format -eq 'excel' -and $Operation -eq 'readRange') { $sheet = if ($null -eq (Get-OptionalParam 'sheet')) { $document.Worksheets.Item(1) } else { $document.Worksheets.Item([string](Get-OptionalParam 'sheet')) }; $range = $sheet.Range([string](Get-RequiredParam 'range')); Output @{ sheet = $sheet.Name; range = $range.Address(); values = $range.Value2 } }
    if ($Format -eq 'excel' -and $Operation -eq 'find') { $query = [string](Get-RequiredParam 'query'); $matches = @(); for ($sheetIndex = 1; $sheetIndex -le $document.Worksheets.Count -and $matches.Count -lt 500; $sheetIndex++) { $sheet = $document.Worksheets.Item($sheetIndex); $used = $sheet.UsedRange; for ($row = 1; $row -le $used.Rows.Count -and $matches.Count -lt 500; $row++) { for ($column = 1; $column -le $used.Columns.Count -and $matches.Count -lt 500; $column++) { $cell = $used.Cells.Item($row, $column); if ([string]$cell.Text -like "*$query*") { $matches += [ordered]@{ sheet = $sheet.Name; address = $cell.Address(); value = [string]$cell.Text } } } } }; Output @{ query = $query; matches = $matches; truncated = $matches.Count -ge 500 } }
    if ($Format -eq 'excel' -and $Operation -eq 'manageNamedRange' -and [string]$request.params.operation -eq 'list') { $items = @(); for ($index = 1; $index -le $document.Names.Count; $index++) { $named = $document.Names.Item($index); $items += [ordered]@{ name = [string]$named.Name; formula = [string]$named.RefersTo } }; Output @{ operation = 'list'; names = $items } }
    if ($Format -eq 'excel' -and $Operation -eq 'managePivotTable' -and [string]$request.params.operation -eq 'list') { $sheet = if ($null -eq (Get-OptionalParam 'sheet')) { $document.Worksheets.Item(1) } else { $document.Worksheets.Item([string](Get-OptionalParam 'sheet')) }; $items = @(); for ($index = 1; $index -le $sheet.PivotTables().Count; $index++) { $pivot = $sheet.PivotTables().Item($index); $items += [ordered]@{ name = [string]$pivot.Name; address = [string]$pivot.TableRange2.Address() } }; Output @{ operation = 'list'; pivots = $items } }
    if ($Format -eq 'pptx' -and $Operation -eq 'readSlide') { $slide = $document.Slides.Item(([int](Get-RequiredParam 'slide')) + 1); $items = @(); foreach ($shape in $slide.Shapes) { if ($shape.HasTextFrame -and $shape.TextFrame.HasText) { $items += @{ name = $shape.Name; text = [string]$shape.TextFrame.TextRange.Text } } }; Output @{ slide = ([int](Get-RequiredParam 'slide')); elements = $items } }
    Fail "The $Format read operation '$Operation' is not supported by the installed Office backend."
  } finally { Office-Close $Format $document $app }
}
function Read-OfficeExtended([string]$Format, [string]$DocumentPath, [string]$Operation) {
  $app = $null; $document = $null
  try {
    $app = Office-App $Format; $app.Visible = $false; $document = Office-Open $Format $DocumentPath $app
    if ($Format -eq 'docs' -and $Operation -eq 'manageRevisions') { Output @{ operation = 'status'; tracked = [bool]$document.TrackRevisions } }
    if ($Format -eq 'docs' -and $Operation -eq 'manageComments') { $items = @(); foreach ($comment in $document.Comments) { $items += [ordered]@{ index = $items.Count; author = [string]$comment.Author; text = Bound-Text ([string]$comment.Range.Text); start = [int]$comment.Scope.Start; end = [int]$comment.Scope.End } }; Output @{ operation = 'list'; comments = $items } }
    if ($Format -eq 'excel' -and $Operation -eq 'manageTable') { $sheet = Office-Sheet $document; $items = @(); foreach ($table in $sheet.ListObjects) { $items += [ordered]@{ name = [string]$table.Name; range = [string]$table.Range.Address() } }; Output @{ operation = 'list'; tables = $items } }
    if ($Format -eq 'excel' -and $Operation -eq 'manageChart') { $sheet = Office-Sheet $document; $items = @(); foreach ($chart in $sheet.ChartObjects()) { $items += [ordered]@{ name = [string]$chart.Name; left = $chart.Left; top = $chart.Top; width = $chart.Width; height = $chart.Height } }; Output @{ operation = 'list'; charts = $items } }
    if ($Format -eq 'excel' -and $Operation -eq 'filterRange') { $sheet = Office-Sheet $document; Output @{ operation = 'list'; sheet = $sheet.Name; filtered = [bool]$sheet.FilterMode; range = if ($null -eq $request.params.range) { $null } else { [string]$request.params.range } } }
    Fail "The $Format extended read operation '$Operation' is not supported by the installed Office backend."
  } finally { Office-Close $Format $document $app }
}

function Export-OfficePdf([string]$Format, [object]$Document, [string]$OutputPath) {
  if ([string]::IsNullOrWhiteSpace($OutputPath)) { throw 'An outputPath is required for document PDF export.' }
  New-Item -ItemType Directory -Path ([IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($OutputPath))) -Force | Out-Null
  if ($Format -eq 'docs') { $Document.ExportAsFixedFormat($OutputPath, 17) }
  elseif ($Format -eq 'excel') { $Document.ExportAsFixedFormat(0, $OutputPath) }
  else { $Document.SaveAs($OutputPath, 32) }
  return $OutputPath
}

function Render-OfficeDocument([string]$Format, [object]$Document, [string]$DocumentPath) {
  $requested = if ($null -eq $request.params.outputPath) { $null } else { [string]$request.params.outputPath }
  $root = if ([string]::IsNullOrWhiteSpace($requested)) { Join-Path ([IO.Path]::GetDirectoryName($DocumentPath)) ([IO.Path]::GetFileNameWithoutExtension($DocumentPath) + '.render') } elseif ([IO.Path]::GetExtension($requested).ToLowerInvariant() -eq '.pdf') { [IO.Path]::GetDirectoryName([IO.Path]::GetFullPath($requested)) } else { $requested }
  New-Item -ItemType Directory -Path $root -Force | Out-Null
  $pdf = if ($null -ne $requested -and [IO.Path]::GetExtension($requested).ToLowerInvariant() -eq '.pdf') { $requested } else { Join-Path $root ([IO.Path]::GetFileNameWithoutExtension($DocumentPath) + '.pdf') }
  Export-OfficePdf $Format $Document $pdf | Out-Null
  $base = [IO.Path]::GetFileNameWithoutExtension($DocumentPath)
  $prefix = Join-Path $root $base
  $selected = Pdf-ExplicitPages
  $files = @()
  if ($null -eq $selected) {
    Run-External 'pdftoppm' @('-png', $pdf, $prefix) | Out-Null
    $files = @(Get-ChildItem -LiteralPath $root -File | Where-Object { $_.Name.StartsWith($base, [StringComparison]::Ordinal) -and $_.Extension -eq '.png' } | Sort-Object Name | ForEach-Object FullName)
  } else {
    for ($index = 0; $index -lt $selected.Count; $index++) {
      $pagePrefix = Join-Path $root ($base + '-page-' + ([int]$selected[$index] + 1).ToString('D4'))
      Run-External 'pdftoppm' @('-png', '-singlefile', '-f', ([string]($selected[$index] + 1)), '-l', ([string]($selected[$index] + 1)), $pdf, $pagePrefix) | Out-Null
      $files += "$pagePrefix.png"
    }
  }
  return @{ path = $root; pdf = $pdf; files = $files }
}

function Write-OfficeExtended([string]$Format, [string]$DocumentPath, [string]$Operation) {
  $app = $null; $document = $null
