    if ($Format -eq 'docs' -and $Operation -eq 'setSection') { $section = $document.Sections.Item(1); $options = Get-OptionalParam 'options'; if ($null -ne $options.marginLeft) { $section.PageSetup.LeftMargin = [float]$options.marginLeft }; if ($null -ne $options.marginRight) { $section.PageSetup.RightMargin = [float]$options.marginRight }; if ($null -ne $options.marginTop) { $section.PageSetup.TopMargin = [float]$options.marginTop }; if ($null -ne $options.marginBottom) { $section.PageSetup.BottomMargin = [float]$options.marginBottom }; $document.Save(); Output @{ saved = $true; operation = $Operation } }
    if ($Format -eq 'docs' -and $Operation -eq 'manageRevisions') { $mode = [string](Get-RequiredParam 'operation'); if ($mode -eq 'enable' -or $mode -eq 'track') { $document.TrackRevisions = $true } elseif ($mode -eq 'disable' -or $mode -eq 'untrack') { $document.TrackRevisions = $false } else { Fail "Unsupported revision operation '$mode'." }; $document.Save(); Output @{ saved = $true; operation = $mode; tracked = [bool]$document.TrackRevisions } }
