    if ($Format -eq 'docs' -and ($Operation -eq 'exportPdf' -or $Operation -eq 'render')) { if ($Operation -eq 'exportPdf') { $output = Export-OfficePdf $Format $document ([string](Get-RequiredParam 'outputPath')); Output @{ path = $output; exported = $true } }; Output (Render-OfficeDocument $Format $document $DocumentPath) }
    if ($Format -eq 'excel') {
