      if ($Operation -eq 'manageTable') { $mode = [string](Get-RequiredParam 'operation'); $range = $sheet.Range([string](Get-RequiredParam 'range')); if ($mode -eq 'create') { $table = $sheet.ListObjects.Add(1, $range, $null, 1); if ($null -ne $request.params.tableName) { $table.Name = [string]$request.params.tableName }; $document.Save(); Output @{ saved = $true; operation = $mode; name = [string]$table.Name } }; $table = $sheet.ListObjects.Item([string](Get-RequiredParam 'tableName')); if ($mode -eq 'update') { $table.Resize($range) } elseif ($mode -eq 'delete') { $table.Unlist() } else { Fail "Unsupported table operation '$mode'." }; $document.Save(); Output @{ saved = $true; operation = $mode; name = [string]$table.Name } }
      if ($Operation -eq 'manageChart') { $mode = [string](Get-RequiredParam 'operation'); $options = Get-OptionalParam 'options'; if ($mode -eq 'create') { $left = if ($null -eq $options.left) { 0 } else { [float]$options.left }; $top = if ($null -eq $options.top) { 0 } else { [float]$options.top }; $width = if ($null -eq $options.width) { 480 } else { [float]$options.width }; $height = if ($null -eq $options.height) { 300 } else { [float]$options.height }; $chart = $sheet.ChartObjects().Add($left, $top, $width, $height); $chart.Name = [string](Get-RequiredParam 'name'); $chart.Chart.SetSourceData($sheet.Range([string](Get-RequiredParam 'sourceRange'))); if ($null -ne $options.title) { $chart.Chart.HasTitle = $true; $chart.Chart.ChartTitle.Text = [string]$options.title } } else { $chart = $sheet.ChartObjects().Item([string](Get-RequiredParam 'name')); if ($mode -eq 'update') { if ($null -ne $options.title) { $chart.Chart.HasTitle = $true; $chart.Chart.ChartTitle.Text = [string]$options.title } } elseif ($mode -eq 'delete') { $chart.Delete() } else { Fail "Unsupported chart operation '$mode'." } }; $document.Save(); Output @{ saved = $true; operation = $mode; name = [string]$request.params.name } }
      if ($Operation -eq 'filterRange') { $mode = [string](Get-RequiredParam 'operation'); $range = $sheet.Range([string](Get-RequiredParam 'range')); if ($mode -eq 'set') { $field = if ($null -eq $request.params.options.field) { 1 } else { [int]$request.params.options.field }; $criteria = if ($null -eq $request.params.options.value) { '*' } else { [string]$request.params.options.value }; $range.AutoFilter($field, $criteria) } elseif ($mode -eq 'clear') { $sheet.AutoFilterMode = $false } else { Fail "Unsupported filter operation '$mode'." }; $document.Save(); Output @{ saved = $true; operation = $mode; range = $range.Address() } }
      if ($Operation -eq 'formatRange') { $range = $sheet.Range([string](Get-RequiredParam 'range')); $options = Get-OptionalParam 'options'; if ($null -ne $options.backgroundColor) { $range.Interior.Color = [int]$options.backgroundColor }; if ($null -ne $options.fontColor) { $range.Font.Color = [int]$options.fontColor }; if ($null -ne $options.bold) { $range.Font.Bold = [bool]$options.bold }; if ($null -ne $options.fontSize) { $range.Font.Size = [float]$options.fontSize }; $document.Save(); Output @{ saved = $true; operation = $Operation; range = $range.Address() } }
      if ($Operation -eq 'sortRange') { $range = $sheet.Range([string](Get-RequiredParam 'range')); $index = if ($null -eq $request.params.index) { 1 } else { [int]$request.params.index + 1 }; $ascending = if ($null -eq $request.params.ascending) { $true } else { [bool]$request.params.ascending }; $range.Sort($range.Columns.Item($index), $(if ($ascending) { 1 } else { 2 })) | Out-Null; $document.Save(); Output @{ saved = $true; operation = $Operation; range = $range.Address() } }
