      if ($Operation -eq 'updateElement' -or $Operation -eq 'deleteElement') { $slide = Office-Slide $document; $shape = $slide.Shapes.Item([string](Get-RequiredParam 'elementId')); if ($Operation -eq 'deleteElement') { $shape.Delete() } else { $options = Get-OptionalParam 'options'; if ($null -ne $request.params.text) { $shape.TextFrame.TextRange.Text = [string]$request.params.text }; if ($null -ne $options.left) { $shape.Left = [float]$options.left }; if ($null -ne $options.top) { $shape.Top = [float]$options.top }; if ($null -ne $options.width) { $shape.Width = [float]$options.width }; if ($null -ne $options.height) { $shape.Height = [float]$options.height } }; $document.Save(); Output @{ saved = $true; operation = $Operation; elementId = [string]$request.params.elementId } }
      if ($Operation -eq 'exportPdf' -or $Operation -eq 'render') { if ($Operation -eq 'exportPdf') { $output = Export-OfficePdf $Format $document ([string](Get-RequiredParam 'outputPath')); Output @{ path = $output; exported = $true } }; Output (Render-OfficeDocument $Format $document $DocumentPath) }
